#!/bin/bash
# Installs a development build of vtium as the console of one VT of this
# machine, so it stays there across reboots, and takes it off again
# (docs/vt-review.md, "Installing vtium on a VT"). make vt-install VT=N and
# make vt-uninstall VT=N run it.
#
#   vt-install.sh install|uninstall [--dry-run] N
#
# install copies the binary VTIUM_VT_BIN to /usr/local/bin/vtium-dev and the
# glyph helper VTIUM_VT_CONFIG to /usr/local/bin/vtium-dev-config, writes
# the unit vtium-dev@.service and its getty fallback
# vtium-dev-getty@.service into /etc/systemd/system, generated by units.sh
# from crates/vtium/install/vtium@.service and vtium-getty@.service,
# records what it did in a manifest, /var/lib/vtium-dev-install/ttyN, then
# stops and disables getty@ttyN and enables and starts vtium-dev@ttyN.
# uninstall reads the manifest and undoes all of it: vtium-dev@ttyN stopped
# and disabled, getty@ttyN enabled and started again where it was before, and
# the files removed once no other VT's manifest needs them. Both remove the
# helper an install made before the tool was renamed vtium-config left at
# /usr/local/bin/vtium-dev-vitrify, while it is still the file that install
# wrote (ADR-1201 D12). One run at a
# time reads and changes the install: each holds a lock on
# /var/lib/vtium-dev-install, and a second run refuses while the first runs.
#
# Every name is the development install's own, so the packaged vtium, whose
# package owns /usr/bin/vtium, /usr/bin/vtium-config, vtium@.service and
# vtium-getty@.service, can run on another VT at the same time. The binary
# looks for its helper at the path it was built with, so install refuses a
# binary that does not name /usr/local/bin/vtium-dev-config, and make
# vt-install builds one that does. The names kmsconvt@ and kmsconvt-getty@
# are left alone: they belong to the C reference's package. The template
# alias /etc/systemd/system/autovt@.service is left alone too, whichever
# console it names: a getty, the C reference's console, or the packaged vtium
# after vtium console enable --all. Enabling vtium-dev@ttyN adds the per-VT
# alias autovt@ttyN.service -> vtium-dev@.service, so that logind, which
# starts autovt@ttyN on a VT nothing holds, starts vtium-dev there and never
# the console the template names. The review runs borrow that VT (vt.sh).
# Neither command touches /etc/vtium/vtium.conf, which vtium reads.
#
# Each command that changes anything runs through sudo and is printed first.
# --dry-run (make DRY_RUN=1) asks what it would ask and prints the units and
# every command, and runs none of them.
#
# For the tests, VTIUM_VT_STANDINS names a directory of stand-ins: sudo,
# systemctl and loginctl run from there, "active" stands for the VT on
# screen, "root" is the directory the installed paths are under, and an
# "install" directory there, when present, stands for crates/vtium/install.
set -euo pipefail

usage() {
	sed -n '7,7s/^# \{0,1\}//p' "$0" >&2
	exit 2
}

die() {
	printf 'vt-install: %s\n' "$*" >&2
	exit 1
}

here=$(cd "$(dirname "$(readlink -f "$0")")" && pwd)
checkout=$(readlink -m "$here/../..")
# shellcheck source=tools/vt/common.sh
. "$here/common.sh"

action=
dry=
vt=
while [ $# -gt 0 ]; do
	case $1 in
	install | uninstall) [ -z "$action" ] || usage; action=$1 ;;
	--dry-run) dry=1 ;;
	-h | --help) usage ;;
	*) [ -z "$vt" ] || usage; vt=$1 ;;
	esac
	shift
done
[ -n "$action" ] || usage
[ -n "$vt" ] || die "VT=N names the VT, 2 to 12"
[[ $vt =~ ^[1-9][0-9]*$ ]] || die "VT must be a number from 2 to 12, not '$vt'"
[ "$vt" != 1 ] || die "VT 1 is refused: it holds the boot's messages and its first login, and a VT that comes back wrong there leaves no console to fix it from"
[ "$vt" -ge 2 ] && [ "$vt" -le 12 ] || die "VT must be a number from 2 to 12, not '$vt'"

standins=${VTIUM_VT_STANDINS:-}
# On the machine it asks sudo for each step that needs root, and prints each
# one first. The tests' stand-ins write only under their own root, so a test
# run as root goes through.
[ -n "$standins" ] || [ "$(id -u)" -ne 0 ] ||
	die "run it as yourself, not as root or under sudo; it asks sudo for each step that needs root"
# As root, the script runs the stand-ins as root, so only root or the user
# who ran sudo may have written them, as run-vt.sh asks of the binary. It
# runs sudo, systemctl and loginctl from the stand-ins' directory by path,
# and the tests put the directory first on PATH, so any other file there
# runs when the script calls a command of that name. The check therefore
# covers the directory and every regular file and symlink in it, and reads
# a symlink's owner and mode from the file it names; a symlink that names no
# file is refused, since its owner cannot be read. Three programs are found
# through PATH before the check is done: bash, which runs this script, id,
# which says whether this is root, and stat, which the check reads the
# owners with. For those three the script trusts PATH, as root trusts its
# PATH.
if [ -n "$standins" ] && [ "$(id -u)" -eq 0 ]; then
	sudo_uid=${SUDO_UID:-0}
	[[ $sudo_uid =~ ^[0-9]+$ ]] || die "SUDO_UID is '$sudo_uid', not a uid"
	shopt -s dotglob nullglob
	checked=("$standins" "$standins/sudo" "$standins/systemctl" "$standins/loginctl")
	for f in "$standins"/*; do
		[ ! -f "$f" ] && [ ! -L "$f" ] || checked+=("$f")
	done
	shopt -u dotglob nullglob
	for f in "${checked[@]}"; do
		read -r owner mode < <(stat -L -c '%u %a' -- "$f") || die "cannot read the owner of $f"
		[ "$owner" -eq 0 ] || [ "$owner" -eq "$sudo_uid" ] ||
			die "$f belongs to uid $owner, neither root nor the user who ran sudo; as root, vt-install runs the stand-ins as root"
		(( (8#$mode & 8#022) == 0 )) ||
			die "$f is writable by group or others (mode $mode); as root, vt-install runs the stand-ins as root"
	done
fi
src=$checkout/crates/vtium/install
if [ -n "$standins" ]; then
	sudo=$standins/sudo
	systemctl=$standins/systemctl
	loginctl=$standins/loginctl
	active_file=$standins/active
	root=$standins/root
	[ ! -d "$standins/install" ] || src=$standins/install
	# The tests run without root, so the files they install stay theirs.
	own=()
else
	sudo=sudo
	systemctl=systemctl
	loginctl=loginctl
	active_file=/sys/class/tty/tty0/active
	root=
	own=(-o root -g root)
fi
bin_path=/usr/local/bin/vtium-dev
helper_path=/usr/local/bin/vtium-dev-config
unit_dir=/etc/systemd/system
state_dir=$vt_install_state
unit=vtium-dev@tty$vt.service
fallback=vtium-dev-getty@tty$vt.service
getty=getty@tty$vt.service
manifest=$state_dir/tty$vt
# The checksum of each file install wrote, one "SHA256  PATH" line each, as
# sha256sum prints them. The files are every VT's, so the record is too.
# While install copies, a file can hold its checksum from before or after
# the copy, so the record holds both until the copies are done.
record=$state_dir/files
# What install writes, by its path on the machine; uninstall removes these.
files=("$bin_path" "$helper_path" "$unit_dir/vtium-dev@.service" "$unit_dir/vtium-dev-getty@.service")
# What an install made before the tool was renamed vtium-config (ADR-1201
# D12) wrote under a name vt-install no longer uses. Install and uninstall
# remove each one the record still holds unchanged, and keep any other.
retired=(/usr/local/bin/vtium-dev-vitrify)
# The per-VT alias that enabling vtium-dev@ttyN makes, and where it points.
alias_link=$unit_dir/autovt@tty$vt.service
alias_target=$unit_dir/vtium-dev@.service

show() {
	printf '+'
	printf ' %q' "$@"
	printf '\n'
}
# Runs a command as root, printed first; a dry run prints it alone.
as_root() {
	show sudo "$@"
	[ -n "$dry" ] || "$sudo" "$@"
}

# The temporary name vt-install writes file $1 under before it renames it
# into place: .NAME.vt-install-new in the same directory, a name only
# vt-install uses. systemd passes over a name that starts with a dot when it
# reads a unit directory.
staged() {
	printf '%s/.%s.vt-install-new' "${1%/*}" "${1##*/}"
}

# put SOURCE PATH MODE: copies SOURCE to PATH as root, with MODE. The copy
# goes to PATH's temporary name and is renamed into place, so PATH holds the
# old file or the whole new one, never part of a file: a copy cut short, as
# on a full disk, leaves only a part at the temporary name, which put then
# removes. sync writes the copy to the disk before the rename, so a power cut
# just after the rename cannot bring PATH back empty.
put() {
	local t
	t=$(staged "$2")
	if ! as_root install -D -m "$3" "${own[@]}" -- "$1" "$root$t" || ! as_root sync -- "$root$t"; then
		as_root rm -f -- "$root$t" || true
		return 1
	fi
	as_root mv -fT -- "$root$t" "$root$2"
}

# Prints each file at one of the temporary names, one a line: the temporary
# name of each file install writes, and every temporary name in the state
# directory, which holds those of the record and of each VT's manifest. A
# run holding the lock (lock_state) finds there only what a run cut short in
# the middle of a copy left, such as a first install killed while it copied
# its manifest.
leftovers() {
	local f t
	for f in "${files[@]}" "${retired[@]}"; do
		t=$root$(staged "$f")
		[ ! -e "$t" ] && [ ! -L "$t" ] || printf '%s\n' "$t"
	done
	# A pattern that matches nothing stays as it is, and names no file.
	for t in "$root$state_dir"/.*.vt-install-new; do
		[ ! -e "$t" ] && [ ! -L "$t" ] || printf '%s\n' "$t"
	done
}

# Takes the lock on the state directory, which must exist, or refuses. Each
# run holds it from before it reads what is installed until it ends, so two
# runs never interleave, and a run that clears the temporary files never
# removes one that another run is still writing. The lock is an flock on the
# directory itself, which the user can open without root, so a run that
# finds the directory takes the lock before it asks sudo for anything. The
# directory is mode 0755 and flock needs only read access, so any local user
# can hold the lock and keep vt-install from running. That only blocks a
# run, never changes the install, and is acceptable on a development machine
# that one person uses.
lock_state() {
	exec 9<"$root$state_dir" || die "cannot open $state_dir to lock it"
	flock -n 9 ||
		die "another make vt-install or make vt-uninstall is running (it holds $state_dir locked); run this again once it ends"
	# The last uninstall removes the directory while it holds the lock. A
	# run that opened the directory before that, and took the lock after,
	# holds the lock on a directory that is gone.
	[ "$root$state_dir" -ef "/proc/$$/fd/9" ] ||
		die "another make vt-install or make vt-uninstall removed $state_dir while this one started; run this again"
}

# Refuses the VT on screen (the desktop's, since this runs from it) and a VT
# a logind session is on, as run-vt.sh does: stopping its unit would end
# that session.
fg=$(cat "$active_file") || die "cannot read $active_file, so the VT on screen is unknown"
fg=${fg#tty}
[[ $fg =~ ^[0-9]+$ ]] || die "$active_file reads '$fg', so the VT on screen is unknown"
[ "$fg" != "$vt" ] || die "VT $vt is on screen now; run this from another VT"
on_vt=$(vt_sessions "$loginctl" "$vt") ||
	die "loginctl could not list the sessions or read one of them, so whether a session is on VT $vt is unknown"
[ -z "$on_vt" ] || die "logind session ${on_vt%% *} is on VT $vt; log out there first"

# The manifests in place, by VT: each VT that vt-install holds has one.
manifests() {
	local m
	for m in "$root$state_dir"/tty*; do
		[ ! -f "$m" ] || printf '%s\n' "${m##*/}"
	done
}

# The checksums the record holds for file $1, one a line, or nothing.
recorded() {
	[ -f "$root$record" ] || return 0
	awk -v f="$1" '$2 == f && $1 ~ /^[0-9a-f]+$/ && length($1) == 64 { print $1 }' "$root$record"
}

# The checksum of file $1 as it is on the machine now.
checksum() {
	sha256sum <"$root$1" | cut -d' ' -f1
}

# Whether file $1 is one install wrote: a regular file whose checksum the
# record holds.
written() {
	[ -f "$root$1" ] && [ ! -L "$root$1" ] && recorded "$1" | grep -qxF -- "$(checksum "$1")"
}

# Removes each retired file that is still the one install wrote, and names
# one the record holds that changed since; one the record does not hold is
# someone else's, and stays without a word.
retire() {
	local f
	for f in "${retired[@]}"; do
		[ -e "$root$f" ] || [ -L "$root$f" ] || continue
		if written "$f"; then
			as_root rm -f -- "$root$f"
		elif [ -n "$(recorded "$f")" ]; then
			echo "vt-$action: kept $f: it changed since vt-install wrote it"
		fi
	done
}

# The value of KEY in the manifest, which install wrote as root: yes or no.
manifest_value() {
	local v
	v=$(sed -n "s/^$1=//p" "$root$manifest")
	[[ $v == yes || $v == no ]] || die "$manifest has no $1=yes or $1=no line; restore VT $vt by hand (docs/vt-review.md)"
	printf '%s' "$v"
}

if [ "$action" = uninstall ]; then
	nothing="no $manifest: make vt-install did not install vtium on VT $vt, so there is nothing to undo"
	[ -d "$root$state_dir" ] || die "$nothing"
	lock_state
	mapfile -t temps < <(leftovers)
	if [ ! -f "$root$manifest" ]; then
		# A first install killed while it copied its manifest leaves the
		# manifest's temporary file and no manifest, and one whose manifest
		# copy failed, or that was killed before the copy, leaves an empty
		# state directory. Uninstall clears what such a run left, and the
		# state directory once nothing else is in it.
		empty=
		[ -n "$(ls -A -- "$root$state_dir")" ] || empty=1
		[ "${#temps[@]}" -gt 0 ] || [ -n "$empty" ] || die "$nothing"
		[ -z "$dry" ] || echo "vt-uninstall: the commands, none of them run:"
		for t in "${temps[@]}"; do
			as_root rm -f -- "$t"
		done
		as_root rmdir --ignore-fail-on-non-empty -- "$root$state_dir"
		if [ -n "$dry" ]; then
			:
		elif [ "${#temps[@]}" -gt 0 ]; then
			echo "vt-uninstall: make vt-install did not install vtium on VT $vt; vt-uninstall removed the temporary files that a run cut short left"
		else
			echo "vt-uninstall: $nothing; vt-uninstall removed the empty $state_dir that a run cut short left"
		fi
		exit 0
	fi
	was_enabled=$(manifest_value getty-enabled)
	was_active=$(manifest_value getty-active)
	others=$(manifests | grep -vx "tty$vt" || true)
	[ -z "$dry" ] || echo "vt-uninstall: the commands, none of them run:"
	# A run cut short before vtium-dev@.service was copied left no unit to
	# stop or disable, and systemctl refuses a unit it cannot find.
	if [ -e "$root$unit_dir/vtium-dev@.service" ]; then
		as_root "$systemctl" stop "$unit"
		as_root "$systemctl" disable "$unit"
	fi
	# disable leaves the per-VT alias autovt@ttyN, so logind would start
	# vtium there again; it goes when it is still the one enable made.
	if [ "$(readlink -- "$root$alias_link" 2>/dev/null)" = "$alias_target" ]; then
		as_root rm -f -- "$root$alias_link"
	fi
	# A unit that failed stays listed as failed until this clears it.
	show sudo "$systemctl" reset-failed "$unit" "$fallback"
	[ -n "$dry" ] || "$sudo" "$systemctl" reset-failed "$unit" "$fallback" 2>/dev/null || true
	# enable would also make the getty's own alias autovt@ttyN.service, which
	# was never there; add-wants makes only the getty.target.wants link that
	# install's disable removed.
	[ "$was_enabled" = no ] || as_root "$systemctl" add-wants getty.target "$getty"
	[ "$was_active" = no ] || as_root "$systemctl" start "$getty"
	for t in "${temps[@]}"; do
		as_root rm -f -- "$t"
	done
	as_root rm -f -- "$root$manifest"
	if [ -n "$others" ]; then
		echo "vt-uninstall: kept ${files[*]}: vt-install holds $(paste -sd' ' <<<"$others") as well"
	else
		# Only a file that is still the one install wrote goes; one changed
		# since is someone's edit, and stays.
		for f in "${files[@]}"; do
			[ -e "$root$f" ] || continue
			if written "$f"; then
				as_root rm -f -- "$root$f"
			else
				echo "vt-uninstall: kept $f: it changed since vt-install wrote it"
			fi
		done
		retire
		as_root rm -f -- "$root$record"
		as_root rmdir --ignore-fail-on-non-empty -- "$root$state_dir"
	fi
	as_root "$systemctl" daemon-reload
	# A template alias autovt@.service that points at vtium-dev@.service is
	# no link vt-install makes: systemctl enable vtium-dev@.service with no VT
	# named makes it on a machine that had none, and logind then starts
	# vtium-dev on every VT it spawns. Uninstall names it and leaves it to
	# whoever made it.
	if [ "$(readlink -- "$root$unit_dir/autovt@.service" 2>/dev/null)" = "$alias_target" ]; then
		echo "vt-uninstall: $unit_dir/autovt@.service points at vtium-dev@.service, so logind starts vtium-dev on every VT it spawns; vt-install did not make it. Remove it: sudo rm $unit_dir/autovt@.service && sudo systemctl daemon-reload"
	fi
	[ -n "$dry" ] || echo "vt-uninstall: VT $vt is back as it was before make vt-install"
	exit 0
fi

# program VARIABLE WHAT HOW: the program the variable names, as an absolute
# path, once it is checked to be one only root or the user could have
# written, since once installed HOW.
program() {
	local p=${!1:-} owner mode
	[ -n "$p" ] || die "$1 names $2; make vt-install sets it"
	p=$(readlink -m -- "$p")
	[ -f "$p" ] && [ -x "$p" ] || die "no $2 at $p: make vt-install builds it"
	read -r owner mode < <(stat -c '%u %a' -- "$p")
	[ "$owner" -eq 0 ] || [ "$owner" -eq "$(id -u)" ] ||
		die "$p belongs to uid $owner, neither root nor you; $3"
	(( (8#$mode & 8#022) == 0 )) || die "$p is writable by group or others (mode $mode); $3"
	printf '%s' "$p"
}
bin=$(program VTIUM_VT_BIN "vtium binary" "it would run as root")
helper=$(program VTIUM_VT_CONFIG "glyph helper" "vtium, as root, would start it")
# vtium starts the helper at the path it was built with (VTIUM_FONT_HELPER,
# crates/vtium/src/helper.rs). One built for another path would start the
# packaged helper, or none.
grep -qaF -- "$helper_path" "$bin" ||
	die "$bin does not look for its glyph helper at $helper_path, so it would start another build's helper or none; make vt-install builds one that looks there"

# The C reference's console, or the packaged vtium, on the VT would fight
# this one for it.
! "$systemctl" is-active --quiet "kmsconvt@tty$vt.service" ||
	die "kmsconvt@tty$vt is running on VT $vt; stop it first, or pick another VT"
packaged=$(vt_packaged "$systemctl" "$vt")
[ -z "$packaged" ] || die "VT $vt refused: $packaged; or pick another VT"

# A run that finds the state directory takes its lock now, before it reads
# what is installed. A first install finds none, and takes the lock once it
# has made the directory, below.
locked=
if [ -d "$root$state_dir" ]; then
	lock_state
	locked=1
fi

# A file at one of the paths is replaced only when it is the one install
# wrote, by the record's checksum; any other is someone else's, or an edit.
for f in "${files[@]}"; do
	[ -e "$root$f" ] || [ -L "$root$f" ] || continue
	[ -n "$(recorded "$f")" ] ||
		die "$f is there already and vt-install did not write it; it is left alone, so nothing is installed"
	written "$f" || die "$f changed since vt-install wrote it; it is left alone, so nothing is installed"
done
# The per-VT alias is enable's to make; one there already, unless it is the
# one an earlier install on this VT made, belongs to someone else.
if [ -e "$root$alias_link" ] || [ -L "$root$alias_link" ]; then
	[ -f "$root$manifest" ] && [ "$(readlink -- "$root$alias_link")" = "$alias_target" ] ||
		die "$alias_link is there already and vt-install did not make it; it is left alone, so nothing is installed"
fi

tmp=$(mktemp -d) || die "cannot create a scratch directory"
trap 'rm -rf -- "$tmp"' EXIT

# The two units, generated from the shipped ones by units.sh, the one place
# both this and the package's make install make them. The unit stops the
# packaged vtium and the C reference's console on its VT before it starts,
# as it stops the getty (ADR-1500 D4).
"$here/units.sh" --name vtium-dev --exec "$bin_path" --by "make vt-install" \
	--conflicts 'vtium@%i.service' --conflicts 'kmsconvt@%i.service' \
	--note "make vt-uninstall removes it." --source "$src" "$tmp" ||
	die "the units could not be generated (above), so nothing is installed"
built=$(git -C "$checkout" describe --always --dirty 2>/dev/null) || built=unknown

# What getty@ttyN was before, so uninstall puts it back: the first install
# on this VT records it, and a reinstall keeps that record.
if [ -f "$root$manifest" ]; then
	echo "vt-install: VT $vt holds vtium-dev already; this installs the build again and restarts it"
	write_manifest=
else
	enabled=$("$systemctl" is-enabled "$getty" 2>/dev/null || true)
	[ "$enabled" = enabled ] && enabled=yes || enabled=no
	"$systemctl" is-active --quiet "$getty" && active=yes || active=no
	cat >"$tmp/manifest" <<EOF
# Written by make vt-install (tools/vt/vt-install.sh) at $built.
# make vt-uninstall VT=$vt reads it to put VT $vt back as it was.
vt=$vt
getty-enabled=$enabled
getty-active=$active
EOF
	write_manifest=1
fi

{
	printf '%s  %s\n' "$(sha256sum <"$bin" | cut -d' ' -f1)" "$bin_path"
	printf '%s  %s\n' "$(sha256sum <"$helper" | cut -d' ' -f1)" "$helper_path"
	for f in vtium-dev@.service vtium-dev-getty@.service; do
		printf '%s  %s\n' "$(sha256sum <"$tmp/$f" | cut -d' ' -f1)" "$unit_dir/$f"
	done
} >"$tmp/files"

if [ -n "$dry" ]; then
	echo "vt-install: the units it would write:"
	for f in vtium-dev@.service vtium-dev-getty@.service; do
		printf '\n--- %s/%s\n' "$unit_dir" "$f"
		cat "$tmp/$f"
	done
	[ -z "$write_manifest" ] || { printf '\n--- %s\n' "$manifest"; cat "$tmp/manifest"; }
	printf '\n--- %s\n' "$record"
	cat "$tmp/files"
	printf '\nvt-install: the commands, none of them run:\n'
else
	"$sudo" -v || die "sudo failed"
	# From here on a step that fails leaves part of the install in place,
	# which the manifest, written first, lets uninstall undo. The message
	# says what uninstall would undo: nothing before the manifest exists, and
	# on a reinstall the earlier install with this run.
	set -E
	trap failed ERR
fi
manifest_written=
failed() {
	if [ -z "$write_manifest" ]; then
		echo "vt-install: a step failed; make vt-uninstall VT=$vt removes the whole install on VT $vt, the earlier one too, and make vt-install VT=$vt tries again" >&2
	elif [ -z "$manifest_written" ]; then
		echo "vt-install: a step failed before anything was installed; VT $vt is as it was" >&2
	else
		echo "vt-install: a step failed; make vt-uninstall VT=$vt undoes what this run did" >&2
	fi
}
# The manifest goes first, so a run cut short can still be undone. After its
# rename, sync writes the state directory to the disk, so the rename is
# there before anything in /usr/local or /etc changes. That matters when
# /var is on a filesystem of its own: a power cut could otherwise keep a
# later rename in /etc and lose the manifest's, leaving files on the
# machine that no manifest names.
[ -d "$root$state_dir" ] || as_root install -d -m 0755 "${own[@]}" -- "$root$state_dir"
if [ -z "$locked$dry" ]; then
	lock_state
	# This run read what is installed while there was no state directory, so
	# a run that has written anything into it since then has changed what
	# this one read.
	[ -z "$(ls -A -- "$root$state_dir")" ] ||
		die "another make vt-install or make vt-uninstall ran while this one started; run this again"
fi
if [ -n "$write_manifest" ]; then
	put "$tmp/manifest" "$manifest" 0644
	as_root sync -- "$root$state_dir"
fi
manifest_written=1
# Each file is written through put, so it holds its content from before the
# run or after it. The record goes before the copies, holding each file's
# checksum from before and after, so a copy that fails leaves every file in a
# state the record knows: uninstall removes it, and a second run replaces it.
{
	cat "$tmp/files"
	for f in "${files[@]}" "${retired[@]}"; do
		! written "$f" || printf '%s  %s\n' "$(checksum "$f")" "$f"
	done
} >"$tmp/files.both"
put "$tmp/files.both" "$record" 0644
put "$helper" "$helper_path" 0755
put "$bin" "$bin_path" 0755
for f in vtium-dev@.service vtium-dev-getty@.service; do
	put "$tmp/$f" "$unit_dir/$f" 0644
done
# The new helper is in place, so the one under its old name goes. The copies
# are done, so the record holds only what is there now.
retire
put "$tmp/files" "$record" 0644
as_root "$systemctl" daemon-reload
# vtium starts first. Its Conflicts=getty@%i stops the getty, and its
# After=getty@%i makes that stop finish before vtium starts, so the getty's
# hangup of the VT cannot reach vtium and the VT is never left with neither.
# The getty is disabled once vtium runs.
as_root "$systemctl" enable "$unit"
as_root "$systemctl" restart "$unit"
as_root "$systemctl" disable "$getty"
[ -n "$dry" ] || cat <<EOF

vt-install: vtium-dev runs on VT $vt, and starts there at every boot.
  Switch to it with Ctrl-Alt-F$vt; Ctrl-Alt-F$fg returns to this desktop.
  make vt-uninstall VT=$vt puts VT $vt back as it was.
EOF
